// ─── OS Event Bus — Mission Control Internal Domain Events ────────────────────
// Events generated by Quinn, the Autonomy Engine, approvals, and the briefing
// pipeline. These are the internal nervous-system signals of Mission Control.

export interface MCAutonomyCyclePayload {
  cycleId: string;
  trigger: "manual" | "scheduled";
  /** ISO timestamp */
  startedAt: string;
}

export interface MCAutonomyCycleCompletedPayload extends MCAutonomyCyclePayload {
  endedAt: string;
  durationMs: number;
  actionsCount: number;
  escalationsCount: number;
  cycleStatus: "success" | "partial" | "failed";
}

export interface MCBriefingPayload {
  briefingId: string;
  objectiveId: string;
  /** One-line headline from the aggregated briefing */
  headline: string;
  /** "healthy" | "attention" | "critical" */
  overallStatus: "healthy" | "attention" | "critical";
  executivesIncluded: string[];
}

export interface MCApprovalPayload {
  approvalId: string;
  objectiveId: string | null;
  /** Why approval was required */
  reason: string;
  /** Which executive created the approval gate */
  requestedBy: string;
  /** "deploy" | "merge" | "delete" | "money" | "external" */
  category: "deploy" | "merge" | "delete" | "money" | "external";
}

export interface MCApprovalDecidedPayload extends MCApprovalPayload {
  /** "approved" | "rejected" */
  decision: "approved" | "rejected";
  /** Who decided (always "founder" in Phase 1+2) */
  decidedBy: string;
  /** Optional rationale */
  rationale: string | null;
}

export interface MCRecommendationPayload {
  recommendationId: string;
  objectiveId: string | null;
  executiveRole: string;
  text: string;
  /** "high" | "medium" | "low" */
  impact: "high" | "medium" | "low";
}

export interface MCLearningInsightPayload {
  insightId: string;
  /** Which founder signal triggered extraction */
  triggerKind: "message" | "decision" | "approval";
  topic: string;
  summary: string;
  confidence: number;
}

export interface MCEventMap {
  "mc.autonomy.cycle_started": MCAutonomyCyclePayload;
  "mc.autonomy.cycle_completed": MCAutonomyCycleCompletedPayload;
  "mc.briefing.generated": MCBriefingPayload;
  "mc.approval.created": MCApprovalPayload;
  "mc.approval.decided": MCApprovalDecidedPayload;
  "mc.recommendation.proposed": MCRecommendationPayload;
  "mc.learning.insight_extracted": MCLearningInsightPayload;
}
